export default {
  name: 'RouteDetail',
  components: {
    RenderDay
  },
  data() {
    return {
      routeDetail: null,
      loading: false,
      loadError: false,
      activeDay: '1',
      exporting: false,
      maps: {} // 地图实例缓存
    };
  },
  computed: {
    // 当前选中天数
    currentDay() {
      if (!this.routeDetail?.itinerary) return null;
      return this.routeDetail.itinerary.find(d => d.dayNum.toString() === this.activeDay);
    },
    // 当前天数景点（地图用）
    currentDayAttractions() {
      return this.currentDay ? this.getDayAttractions(this.currentDay) : [];
    }
  },
  watch: {
    // 监听天数切换
    activeDay() {
      this.$nextTick(() => setTimeout(() => this.initDayMap(), 300));
    },
    // 数据加载完成初始化地图
    routeDetail: {
      handler(val) {
        if (val?.itinerary?.length) {
          this.$nextTick(() => setTimeout(() => this.initDayMap(), 500));
        }
      },
      immediate: true
    }
  },
  mounted() {
    this.loadRouteDetail();
    this.loadAMapScript();
    window.addEventListener('resize', this.handleResize);
  },
  beforeDestroy() {
    // 统一销毁所有地图
    Object.values(this.maps).forEach(map => map?.destroy());
    window.removeEventListener('resize', this.handleResize);
  },
  methods: {
    // 切换天数
    switchDay(dayNum) {
      this.activeDay = dayNum.toString();
    },
    // 类型样式/图标
    getTypeClass(type) {
      return {
        attraction: 'attraction',
        food: 'food',
        hotel: 'hotel',
        route: 'route'
      }[type] || '';
    },
    getTypeIcon(type) {
      return {
        attraction: 'el-icon-location-outline',
        food: 'el-icon-food',
        hotel: 'el-icon-office-building',
        route: 'el-icon-direction'
      }[type] || 'el-icon-more';
    },
    // 展开/收起描述
    toggleDescription(item) {
      this.$set(item, 'showFull', !item.showFull);
    },
    // 获取单日景点（地图用）
    getDayAttractions(day) {
      if (!day?.items) return [];
      const attractions = [];
      const addedKeys = new Set();
      const firstRoute = day.items.find(item => item.type === 'route');
      const startLng = firstRoute?.fromLongitude;
      const startLat = firstRoute?.fromLatitude;

      // 添加起点
      if (firstRoute?.fromLocation && startLng && startLat) {
        const key = `${startLng},${startLat}`;
        addedKeys.add(key);
        attractions.push({
          name: firstRoute.fromLocation.trim(),
          longitude: startLng,
          latitude: startLat,
          type: 'route'
        });
      }

      // 添加点位（去重）
      day.items.filter(i => i.longitude && i.latitude).forEach(item => {
        const key = `${item.longitude},${item.latitude}`;
        if (addedKeys.has(key)) return;
        addedKeys.add(key);
        let name = '未知点位';
        if (item.type === 'attraction') name = item.attractionName;else if (item.type === 'food') name = item.foodName || item.shopName;else if (item.type === 'hotel') name = item.hotelName;else if (item.type === 'route') name = item.toLocation;
        attractions.push({
          name: name.trim() || '未知点位',
          longitude: item.longitude,
          latitude: item.latitude,
          type: item.type
        });
      });
      return attractions;
    },
    // 加载行程详情
    async loadRouteDetail() {
      const id = this.$route.params.id;
      if (!id) {
        this.$message.error('缺少路线ID');
        return this.goBack();
      }
      this.loading = true;
      this.loadError = false;
      try {
        const res = await request({
          url: `${config.backHost}/api/routeRecommendation/detail/${id}`,
          method: 'POST'
        });
        if (res.code === 200 && res.data) this.routeDetail = res.data;else {
          this.$message.error(res.msg || '加载失败');
          this.loadError = true;
        }
      } catch (err) {
        console.error(err);
        this.$message.error('加载失败');
        this.loadError = true;
      } finally {
        this.loading = false;
      }
    },
    // 返回
    goBack() {
      this.$router.go(-1);
    },
    // 工具方法
    getImages(imagesStr) {
      if (!imagesStr) return [];
      try {
        return JSON.parse(imagesStr);
      } catch {
        return imagesStr.split(',').filter(Boolean);
      }
    },
    getTransportText(type) {
      return {
        drive: '自驾',
        bus: '公交',
        taxi: '打车',
        walking: '步行',
        walk: '步行'
      }[type] || type;
    },
    getTypeText(type) {
      return {
        attraction: '景点',
        food: '美食',
        hotel: '酒店',
        route: '交通'
      }[type] || '未知';
    },
    formatDuration(minutes) {
      if (minutes === undefined) return '暂无数据';
      const h = Math.floor(minutes / 60);
      const m = minutes % 60;
      return h ? `${h}小时${m ? m + '分钟' : ''}` : `${m}分钟`;
    },
    getCostClass(summary) {
      return summary.estimatedCost <= summary.budget ? 'under-budget' : 'over-budget';
    },
    // 页面跳转
    goToAttractionDetail(id) {
      id && this.$router.push({
        name: 'attractionDetail',
        query: {
          id
        }
      });
    },
    goToHotelDetail(id) {
      id && this.$router.push({
        name: 'hotelInfoDetail',
        query: {
          id
        }
      });
    },
    goToFoodDetail(id) {
      id && this.$router.push({
        name: 'foodDetail',
        query: {
          id
        }
      });
    },
    handleFoodClick(item) {
      this.goToFoodDetail(item.foodInfoId || item.id || item.foodId);
    },
    // 打开导航
    openNavigation(item) {
      if (!item.fromLongitude || !item.toLongitude) return this.$message.warning('坐标不完整');
      const from = `${item.fromLongitude},${item.fromLatitude}`;
      const to = `${item.toLongitude},${item.toLatitude}`;
      const mode = {
        bus: 'bus',
        walk: 'walk',
        walking: 'walk'
      }[item.transportType] || 'drive';
      window.open(`https://uri.amap.com/navigation?from=${from}&to=${to}&mode=${mode}`, '_blank');
    },
    // 加载高德地图
    loadAMapScript() {
      if (window.AMap) return;
      const script = document.createElement('script');
      script.src = 'https://webapi.amap.com/maps?v=2.0&key=ce1da13e89ae4c9a4dfdde2447fba5a7';
      script.onload = () => this.initDayMap();
      script.onerror = () => this.$message.error('地图加载失败');
      document.head.appendChild(script);
    },
    // 初始化地图
    initDayMap() {
      if (!window.AMap || !this.currentDay) return;
      const dayNum = this.currentDay.dayNum;
      const container = this.$refs[`mapContainer${dayNum}`];
      const el = Array.isArray(container) ? container[0] : container;
      if (!el) return;
      const points = this.currentDayAttractions;
      if (!points.length) return;

      // 销毁旧实例
      this.maps[dayNum]?.destroy();
      const map = new AMap.Map(el, {
        zoom: 12,
        center: [points[0].longitude, points[0].latitude],
        mapStyle: 'amap://styles/light'
      });
      this.maps[dayNum] = map;

      // 绘制路线
      const path = points.map(p => [p.longitude, p.latitude]);
      map.add(new AMap.Polyline({
        path,
        strokeColor: '#FF7A2F',
        strokeWeight: 4
      }));

      // 添加标记
      points.forEach((p, i) => {
        const marker = new AMap.Marker({
          position: [p.longitude, p.latitude],
          content: `<div style="width:28px;height:28px;background:#FF7A2F;color:white;border-radius:50%;display:flex;align-items:center;justify-content:center;border:3px solid #fff;">${i + 1}</div>`,
          offset: new AMap.Pixel(-14, -14)
        });
        map.add(marker);
      });
      map.setFitView();
    },
    // 窗口resize
    handleResize() {
      const map = this.maps[this.currentDay?.dayNum];
      map?.resize?.();
    },
    // ==================== 核心：优化PDF导出（支持全部天数） ====================
    async exportPDF() {
      if (!this.routeDetail) return this.$message.warning('暂无数据');
      this.exporting = true;
      const loading = this.$loading({
        text: '正在生成PDF...'
      });
      try {
        const html2canvas = (await import('html2canvas')).default;
        const jsPDF = (await import('jspdf')).default;
        await this.$nextTick();
        const element = this.$refs.pdfContent;
        if (!element) throw new Error('导出容器不存在');

        // 截图生成PDF
        const canvas = await html2canvas(element, {
          scale: 2,
          useCORS: true,
          backgroundColor: '#fcf9f7',
          ignoreElements: el => el.classList.contains('no-print')
        });
        const pdf = new jsPDF('p', 'mm', 'a4');
        const imgWidth = 210;
        const imgHeight = canvas.height * imgWidth / canvas.width;
        let heightLeft = imgHeight;
        let pos = 0;
        pdf.addImage(canvas.toDataURL('image/png'), 'PNG', 0, pos, imgWidth, imgHeight);
        heightLeft -= 297;
        while (heightLeft >= 0) {
          pos = heightLeft - imgHeight;
          pdf.addPage();
          pdf.addImage(canvas.toDataURL('image/png'), 'PNG', 0, pos, imgWidth, imgHeight);
          heightLeft -= 297;
        }
        pdf.save(`${this.routeDetail.recommendationName || '旅游行程'}.pdf`);
        this.$message.success('PDF导出成功！');
      } catch (err) {
        console.error(err);
        this.$message.error('导出失败：' + err.message);
      } finally {
        loading.close();
        this.exporting = false;
      }
    }
  }
};
